from batch07 import *
start('dns','DNS — nazwy i rozwiązywanie problemów','4.3',['https://www.cisco.com/c/en/us/td/docs/routers/ios-xe/ip-addressing/ip-addressing/m_configuring_dns.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr_dns/configuration/xe-16-6/dns-xe-16-6-book/configuring_dns.html'])
q('Rola DNS','Co typowo uzyskuje aplikacja, pytając DNS o rekord A nazwy serwera?','Adres IPv4 powiązany z nazwą',['Adres MAC serwera w zdalnym LAN-ie|DNS A nie zwraca adresu MAC.','Hasło administratora|DNS nie jest magazynem haseł logowania.','Trasę OSPF do wszystkich sieci|DNS nie zastępuje protokołu routingu.'],'Rozwiązanie nazwy dostarcza adres; nie potwierdza jeszcze łączności z usługą.')
q('AAAA','Jaki typ adresu reprezentuje rekord AAAA?','IPv6',['IPv4|Adresy IPv4 są w rekordach A.','MAC Ethernet|AAAA nie jest rekordem warstwy drugiej.','Numer portu TCP|Port nie jest adresem IPv6.'],'Nazwa może mieć jednocześnie rekordy A i AAAA; ich użycie zależy od klienta i dostępności stosów.')
c('Resolver routera','Ustaw dla własnych zapytań DNS routera serwer 192.0.2.53.','R1(config)# ip name-server {{b0}}',[(['192.0.2.53'],'ipv4')],'ip name-server wskazuje resolver dla urządzenia; samo nie konfiguruje klientów DHCP.')
q('CNAME','Do czego służy rekord CNAME?','Do wskazania aliasu na inną nazwę DNS',['Do zapisania wildcard ACL|To nie konfiguracja filtra IP.','Do wskazania bezpośrednio adresu MAC|CNAME zawiera nazwę, nie MAC.','Do uruchamiania sesji TCP|DNS nie wykonuje za klienta połączenia aplikacji.'],'Rozwiązanie aliasu może wymagać dalszego wyszukania adresu nazwy docelowej.')
c('Tabela nazw IOS','Wyświetl lokalne i buforowane informacje o nazwach w IOS.','R1# show {{b0}}',['hosts'],'show hosts pomaga rozróżnić ustawienia DNS oraz lokalne/buforowane wpisy nazw.')
q('TTL rekordu','Co określa TTL odpowiedzi DNS z punktu widzenia cache?','Czas, przez który wpis może być przechowywany zgodnie z TTL',['Liczbę routerów do serwera|To inne użycie nazwy TTL w nagłówku IP.','Długość hasła DNS|TTL nie dotyczy hasła.','Liczbę wszystkich hostów w domenie|TTL nie jest limitem rozmiaru strefy.'],'TTL cache DNS i TTL pakietu IP są różnymi mechanizmami.')
q('Resolver a authoritative','Który opis pasuje do autorytatywnego serwera danej strefy?','Publikuje odpowiedzi na podstawie utrzymywanych danych tej strefy',['Zawsze jest bramą domyślną klienta|Rola DNS nie oznacza routingu LAN-u.','Wyłącznie przechowuje cudze odpowiedzi w cache|To nie pełny opis roli autorytatywnej.','Nie może odpowiedzieć o własnej strefie|To przeczy tej roli.'],'Resolver może szukać odpowiedzi w imieniu klienta; serwer autorytatywny jest źródłem danych strefy.')
q('NXDOMAIN','Co oznacza odpowiedź DNS NXDOMAIN dla pytanej nazwy?','Pytana nazwa nie istnieje według uzyskanej odpowiedzi DNS',['Timeout bez żadnej odpowiedzi|NXDOMAIN jest otrzymaną odpowiedzią, nie samą ciszą.','Serwer TCP 443 odrzucił sesję|To nie kod aplikacji HTTPS.','Wszystkie sieci IP są nieosiągalne|Odpowiedź DNS nie przesądza o całej sieci.'],'Należy sprawdzić poprawność nazwy i właściwy resolver/strefę; nie mylić tego z timeoutem.')
c('Włącz i wskaż DNS','Router ma wyłączone rozwiązywanie DNS. Włącz je składnią ip domain lookup i wskaż resolver 192.0.2.54.','R1(config)# ip domain {{b0}}\nR1(config)# ip name-server {{b1}}',['lookup',(['192.0.2.54'],'ipv4')],'Konfiguracja serwera i włączenie rozwiązywania to osobne ustawienia urządzenia.')
q('UDP i TCP DNS','Czy prawidłowa obsługa klasycznego DNS może wymagać przepuszczenia TCP 53, oprócz UDP 53?','Tak',['Nie, DNS nigdy nie korzysta z TCP|DNS może używać obu transportów.','Nie, TCP jest zawsze na 443|Port zależy od usługi i konfiguracji.','Tak, lecz tylko dla ARP|ARP nie korzysta z TCP.'],'Odpowiedzi i operacje DNS mogą wymagać TCP; samo UDP bywa niewystarczające.')
c('Statyczna nazwa w labie','Dodaj lokalny wpis lab-router → 10.0.0.9, a następnie pokaż tabelę nazw.','R1(config)# ip host lab-router {{b0}}\nR1(config)# end\nR1# show {{b1}}',[(['10.0.0.9'],'ipv4'),'hosts'],'Lokalne mapowanie ułatwia test, lecz nie aktualizuje automatycznie centralnej strefy DNS.')
q('Usługa po IP a nazwa','Usługa jest osiągalna po adresie IP, a rozwiązanie jej nazwy kończy się timeoutem. Co zbadać najpierw?','Dostępność skonfigurowanego resolvera i ruch zapytań/odpowiedzi DNS',['Zmienić losowo MTU wszystkich routerów|Brak przesłanek do tak szerokiej zmiany.','Uznać, że routing do usługi na pewno nie działa|Test po IP potwierdził przynajmniej badaną drogę do usługi.','Wyłączyć tablicę MAC switcha|Nie jest to celowana diagnostyka DNS.'],'Oddziel rozwiązanie nazwy od połączenia z aplikacją; każde może zawieść niezależnie.')
q('Split DNS','Ta sama nazwa ma inne odpowiedzi w sieci firmowej i poza nią. Czy zawsze jest to błąd?','Nie, może to być zamierzony split DNS',['Tak, nazwa zawsze musi mieć jeden globalny adres|DNS może stosować różne widoki i odpowiedzi.','Tak, oznacza automatycznie konflikt MAC|DNS nie porównuje w ten sposób MAC.','Nie, bo klient nigdy nie używa otrzymanego IP|Klient zwykle właśnie korzysta z rozwiązania nazwy.'],'Ocena zależy od projektu i użytego resolvera; różnica sama nie dowodzi awarii.')
q('Cache po zmianie','Po zmianie rekordu część klientów nadal widzi stare IP. Co może być normalnym wyjaśnieniem?','Wcześniejsza odpowiedź nadal jest ważna w cache',['Wszyscy klienci muszą widzieć zmianę natychmiast|Cache może opóźnić widoczność.','Zmiana rekordu zawsze wyłącza interfejs serwera|Nie jest to automatyczny skutek.','TTL DNS oznacza zmianę trasy statycznej|To inny mechanizm.'],'Widoczność zmiany zależy od cache oraz TTL wcześniej otrzymanej odpowiedzi.')
c('Dwa resolvery i kontrola','Skonfiguruj resolvery 192.0.2.53 oraz 198.51.100.53 w podanej kolejności, włącz lookup i pokaż tabelę nazw.','R1(config)# ip name-server {{b0}} {{b1}}\nR1(config)# ip domain {{b2}}\nR1(config)# end\nR1# show hosts',[(['192.0.2.53'],'ipv4'),(['198.51.100.53'],'ipv4'),'lookup'],'Dwa adresy zwiększają dostępność tylko wtedy, gdy serwery i ich drogi rzeczywiście działają.')
q('DNS działa, HTTPS nie','Rekord A zwraca oczekiwane IP, ale HTTPS nadal nie działa. Co wynika z tego testu?','Rozwiązano nazwę; transport, TLS i aplikacja wymagają osobnej weryfikacji',['DNS gwarantuje działający certyfikat|DNS A nie waliduje TLS.','DNS gwarantuje otwarty port 443|Rekord nie testuje portu.','Trzeba koniecznie usunąć poprawny rekord|Nie ma takiej podstawy.'],'Poprawny adres jest jednym z etapów, nie dowodem działania całej usługi.')
c('Usuń błędny lokalny wpis','W labie błędnie przypisano lab-router do starego IP. Usuń lokalny wpis, wskaż resolver 192.0.2.53 i pokaż hosty.','R1(config)# no ip host {{b0}}\nR1(config)# ip name-server {{b1}}\nR1(config)# end\nR1# show {{b2}}',['lab-router',(['192.0.2.53'],'ipv4'),'hosts'],'Usunięcie statycznego mapowania pozwala korzystać z DNS, jeśli lookup jest aktywne i nazwa jest rozwiązywalna.')
q('PTR','Jaki rekord typowo służy w DNS do odwrotnego mapowania adresu na nazwę?','PTR',['A|A mapuje nazwę na IPv4.','AAAA|AAAA mapuje nazwę na IPv6.','MX|MX wskazuje obsługę poczty domeny.'],'Odwrotne mapowanie ma własne dane i nie musi pojawić się automatycznie po dodaniu A.')
end()
start('aaa','AAA — tożsamość, uprawnienia i audyt','5.8',['https://www.cisco.com/c/en/us/td/docs/ios/sec_user_services/configuration/guide/convert/aaa/sec_cfg_authentifcn.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec_usr_aaa/configuration/xe-16/sec-usr-aaa-xe-16-book.pdf'])
q('Authentication','Na jakie pytanie przede wszystkim odpowiada uwierzytelnianie?','Kim jest podmiot próbujący uzyskać dostęp?',['Jakie dokładnie komendy wolno mu wykonać?|To zagadnienie autoryzacji.','Co zrobił podczas wczorajszej sesji?|To zagadnienie rejestrowania aktywności.','Która trasa ma najniższą metrykę?|To wybór trasy, nie AAA.'],'Authentication potwierdza tożsamość na podstawie przyjętej metody i poświadczeń.')
q('Authorization','Który przykład najlepiej przedstawia autoryzację?','Zezwolenie operatorowi na show, ale odmowa zmian konfiguracji',['Weryfikacja poprawności hasła|To uwierzytelnianie.','Zapis czasu rozpoczęcia sesji|To rejestrowanie aktywności, czyli accounting, a nie decyzja o uprawnieniach.','Obliczenie kosztu OSPF|To nie funkcja AAA.'],'Tożsamość i zakres uprawnień to odrębne decyzje.')
c('Włączenie AAA w labie','Na izolowanym routerze z dostępem konsolowym i przygotowanym kontem lokalnym włącz model AAA.','R1(config)# aaa {{b0}}',['new-model'],'Włączanie AAA zmienia obsługę dostępu; konfigurację należy sprawdzać w labie z zachowaną drogą administracyjną.')
q('Accounting','Który przykład odpowiada accounting?','Rejestrowanie rozpoczęcia i zakończenia sesji administratora',['Wyłącznie porównanie hasła|To authentication.','Wyłącznie pozwolenie na configure terminal|To authorization.','Nadanie numeru VLAN-u|To konfiguracja sieci, nie definicja accounting.'],'Accounting tworzy dane o użyciu usług i działaniach, zależnie od konfiguracji.')
c('Lokalna lista logowania','AAA jest aktywne, a konto lokalne istnieje. Utwórz nazwaną listę LAB korzystającą z lokalnej bazy.','R1(config)# aaa authentication login LAB {{b0}}',['local'],'Nazwana lista metod musi zostać użyta we właściwym miejscu konfiguracji.')
c('Przypięcie listy do VTY','Lista LAB już istnieje. Jesteś w line vty 0 4. Przypisz ją do logowania.','R1(config-line)# login authentication {{b0}}',[(['LAB'],'identifier')],'Utworzenie nazwanej listy i jej przypisanie do linii są osobnymi krokami.')
q('RADIUS i transport','Która para portów jest typowa dla klasycznego RADIUS authentication/accounting po UDP?','1812 i 1813',['22 i 23|To typowe porty SSH i Telnet.','80 i 443|To porty HTTP i HTTPS.','49 i 179|49 kojarzy się z TACACS+, a 179 z BGP.'],'Dla klasycznego RADIUS typowo używa się UDP 1812/1813; istnieją inne warianty i starsze porty.')
q('TACACS+','Jaki transport i port jest typowy dla klasycznego TACACS+?','TCP 49',['UDP 53|To typowy DNS, nie TACACS+.','TCP 443|To zwykle HTTPS.','UDP 1812|To typowy RADIUS authentication.'],'Przy diagnostyce rozróżniaj serwer, protokół i wymagany transport.')
c('TACACS+ z fallbackiem','W labie serwery TACACS+ oraz konto lokalne są przygotowane. Lista MGMT ma próbować grupy tacacs+, a przy niedostępności serwerów — bazy lokalnej.','R1(config)# aaa authentication login MGMT group {{b0}} {{b1}}',['tacacs+','local'],'Fallback do kolejnej metody zwykle zachodzi przy błędzie/niedostępności poprzedniej, nie przy jawnym odrzuceniu hasła.')
q('Reject a timeout','Serwer AAA odpowiada jawnym odrzuceniem uwierzytelnienia. Czy lista group tacacs+ local powinna automatycznie pozwolić spróbować lokalnego hasła?','Nie, jawne odrzucenie nie jest tym samym co niedostępność',['Tak, local zawsze omija decyzję serwera|To błędna interpretacja fallbacku.','Tak, jeśli nazwa konta jest krótka|Długość nazwy nie zmienia reguły.','Tak, bo TACACS+ działa bez sesji TCP|TACACS+ używa TCP; nie wyjaśnia to fallbacku.'],'Polityka fallbacku nie służy do omijania negatywnej decyzji działającego serwera.')
c('RADIUS i lokalny zapas','Przygotowana grupa radius ma być pierwszą metodą, local zapasem w nazwanej liście REMOTE.','R1(config)# aaa authentication login REMOTE group {{b0}} {{b1}}',['radius','local'],'Fallback musi być przetestowany przy rzeczywistej utracie dostępności serwera, nie tylko przy błędnym haśle.')
q('Login nie oznacza pełnych praw','Użytkownik poprawnie się zalogował, ale nie może wykonać komendy. Który obszar sprawdzić?','Autoryzację i poziom uprawnień',['Wyłącznie retransmisje SYN|Sesja logowania już działa, a odmowa może być polityką.','Od razu wyłączyć accounting|Rejestracja działań nie jest oczywistą przyczyną odmowy.','Zmienić VLAN wszystkich użytkowników|Nie jest celowaną kontrolą uprawnień.'],'Udane authentication nie gwarantuje pozwolenia na każdą operację.')
q('Dwie tożsamości','Dlaczego indywidualne konta administratorów są lepsze do audytu niż jedno wspólne konto?','Ułatwiają przypisanie działań konkretnej tożsamości',['Automatycznie eliminują wszystkie ataki|Same konta nie zapewniają pełnego bezpieczeństwa.','Zawsze zwiększają przepustowość WAN|To nie ich funkcja.','Zastępują konieczność logowania zdarzeń|Audyt nadal wymaga rejestracji.'],'Wspólne konto osłabia rozliczalność, nawet jeśli samo logowanie działa poprawnie.')
q('Synchronizacja audytu','Dlaczego przy logach AAA potrzebna jest spójna synchronizacja czasu?','Aby wiarygodnie korelować działania i zdarzenia między urządzeniami',['Aby hasło miało więcej znaków|NTP nie zmienia długości hasła.','Aby TACACS+ zmienił się w RADIUS|Synchronizacja nie zmienia protokołu.','Aby interfejs przestał potrzebować IP|Czas nie zastępuje adresacji.'],'Logi bez zgodnego czasu mogą prowadzić do błędnej kolejności zdarzeń.')
c('Lokalna lista i tylko SSH','Na izolowanym labie AAA i SSH już działają, konto lokalne istnieje. Utwórz listę LOCAL-LAB, przypisz do VTY 0–4 i dopuść tylko SSH.','R1(config)# aaa authentication login LOCAL-LAB {{b0}}\nR1(config)# line vty 0 4\nR1(config-line)# login authentication {{b1}}\nR1(config-line)# transport input {{b2}}',['local',(['LOCAL-LAB'],'identifier'),'ssh'],'Lista metod określa sprawdzenie tożsamości, a transport input ogranicza sposób dostępu.')
q('Sekret współdzielony AAA','Urządzenie i serwer mają niezgodny shared secret. Co należy sprawdzić?','Zgodność sekretu i konfiguracji klienta AAA po obu stronach',['Tylko opis interfejsu LAN|Nie naprawia parametrów AAA.','Zwiększyć limit MAC port-security|To inna funkcja.','Usunąć wszystkie konta lokalne|To nieuzasadniona zmiana i utrata możliwości administracji.'],'Niezgodność sekretu może zaburzać wymianę AAA; ustalaj przyczynę na podstawie logów obu stron.')
c('Metoda zdalna i przypisanie','W labie istnieją serwery TACACS+ i lokalne konto zapasowe. Utwórz listę OPS: tacacs+ potem local, i przypisz do VTY 0–4.','R1(config)# aaa authentication login OPS group {{b0}} {{b1}}\nR1(config)# line vty 0 4\nR1(config-line)# login authentication {{b2}}',['tacacs+','local',(['OPS'],'identifier')],'Test musi obejmować poprawne logowanie, odmowę i niedostępność serwera; to trzy różne przypadki.')
q('Least privilege','Jak zastosować zasadę najmniejszych uprawnień w AAA?','Nadać rolom tylko uprawnienia potrzebne do ich zadań',['Każdemu nadać pełny dostęp na wszelki wypadek|To zaprzecza ograniczaniu uprawnień.','Wyłączyć logowanie zdarzeń dla administratorów|To osłabia audyt, a nie zakres praw.','Zastąpić wszystkie konta wspólnym hasłem|To osłabia rozliczalność.'],'Uprawnienia należy wiązać z rolą i obowiązkami, a wyjątki kontrolować.')
end()
